#![allow(unused)]
use verus::prelude::*;

verus! {

    /// In-place reverse of the inclusive prefix `0..=num` of a non-empty Vec<i32>.
    ///
    /// Requires:
    /// - `a.len() > 0`
    /// - `num < a.len()`
    ///
    /// Ensures:
    /// - The length of `a` is unchanged.
    /// - For every `k` with `0 <= k <= num`, `a[k] == old(a)[num - k]`.
    /// - For every `k` with `num < k < a.len()`, `a[k] == old(a)[k]`.
    fn flip(a: &mut Vec<i32>, num: usize)
        requires
            a.len() > 0,
            num < a.len(),
        ensures
            a.len() == old(a).len(),
            forall |k: usize| k <= num ==> a[k] == old(a)[num - k],
            forall |k: usize| num < k && k < a.len() ==> a[k] == old(a)[k]
    {
        // Snapshot the original array for postcondition reasoning
        ghost let old_a = a.clone();

        // Two‐pointer reversal of prefix [0..=num]
        let mut i: usize = 0;
        let mut j: usize = num;
        while i < j
            invariant
                // pointers stay roughly in bounds
                i <= j + 1,
                j < a.len(),

                // array length is never changed
                a.len() == old_a.len(),

                // positions beyond `num` are unchanged
                forall |k: usize| num < k && k < a.len() ==> a[k] == old_a[k],

                // positions already swapped at the low end satisfy the flip property
                forall |k: usize| k < i ==> a[k] == old_a[num - k],

                // positions already swapped at the high end satisfy the flip property
                forall |k: usize| j < k && k <= num ==> a[k] == old_a[num - k],

                // the middle (unprocessed) segment is still its original values
                forall |k: usize| i <= k && k <= j ==> a[k] == old_a[k],

            decreases
                // measure decreases every iteration (j+1-i ≥ 1) 
                j + 1 - i
        {
            // swap a[i] and a[j]
            let tmp = a[i];
            a[i] = a[j];
            a[j] = tmp;

            i += 1;
            j -= 1;
        }

        // Re‐establish the postconditions against the snapshot
        assert(a.len() == old_a.len());
        assert(forall |k: usize| k <= num ==> a[k] == old_a[num - k]);
        assert(forall |k: usize| num < k && k < a.len() ==> a[k] == old_a[k]);
    }
}